from collections import deque

def halo_pred(inp, output_filter='region4', ngh=8, edge=True, erase_outside=False):
    R,C=len(inp),len(inp[0]); marker=next((r,c) for r in range(R) for c in range(C) if inp[r][c]==6)
    # get connected 8-components of background 8 attached to marker by 4/8 adjacency
    dirs4=[(-1,0),(1,0),(0,-1),(0,1)]
    dirs8=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
    conn=dirs4 if output_filter=='region4' else dirs8 if output_filter=='region8' else []
    reg=set(); q=deque()
    for dr,dc in conn:
      rr,cc=marker[0]+dr,marker[1]+dc
      if 0<=rr<R and 0<=cc<C and inp[rr][cc]==8: q.append((rr,cc))
    while q:
      p=q.popleft()
      if p in reg: continue
      reg.add(p)
      for dr,dc in conn:
        rr,cc=p[0]+dr,p[1]+dc
        if 0<=rr<R and 0<=cc<C and inp[rr][cc]==8 and (rr,cc) not in reg:q.append((rr,cc))
    out=[row[:] for row in inp]
    # halo adjacency to 1
    near=dirs8 if ngh==8 else dirs4
    for r,c in reg:
      adj1=any(0<=r+dr<R and 0<=c+dc<C and inp[r+dr][c+dc]==1 for dr,dc in near)
      bd=edge and (r==0 or c==0 or r==R-1 or c==C-1)
      if adj1 or bd:out[r][c]=7
    if erase_outside:
      # set isolated 1 objects? ignoring for now
      pass
    return out,reg

