def local_rule_stats(samples, radius=1):
 from collections import defaultdict
 by=defaultdict(lambda: {'7':0,'8':0,'other':0,'examples':[]})
 for inp,out in samples:
  R,C=len(inp),len(inp[0])
  for r in range(R):
   for c in range(C):
    if inp[r][c]!=8: continue
    pat=[]
    for dr in range(-radius,radius+1):
     for dc in range(-radius,radius+1):
      rr,cc=r+dr,c+dc
      pat.append(inp[rr][cc] if 0<=rr<R and 0<=cc<C else -1)
    k=tuple(pat)
    by[k][str(out[r][c]) if out[r][c] in(7,8) else 'other']+=1
    by[k]['examples'].append((r,c,out[r][c],len(inp),len(inp[0])))
 return by
